using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, P;
    cin >> N >> M >> P;

    vector<int> row(N), col(M);
    iota(row.begin(), row.end(), 1);
    iota(col.begin(), col.end(), 1);

    for (int k = 0; k < P; k++) {
        char op;
        int a, b;
        cin >> op >> a >> b;
        --a; --b;

        if (op == 'L') {
            swap(row[a], row[b]);
        } else {
            swap(col[a], col[b]);
        }
    }

    for (int i = 0; i < N; i++) {
        int base = (row[i] - 1) * M;
        for (int j = 0; j < M; j++) {
            if (j > 0) cout << ' ';
            cout << base + col[j];
        }
        cout << '\n';
    }

    return 0;
